describe('ToolRegistry.execute', () => {
  it('returns a ToolResponse naming the missing required field and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_address',
        description: 'Look up an address by postal code',
        inputSchema: {
          type: 'object',
          properties: {postalCode: {type: 'string'}},
          required: ['postalCode'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('lookup_address', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/postalCode.*required|required.*postalCode/i),
    });
  });

  it('reports a nested missing required property with its full field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_address',
        description: 'Look up an address by country',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {country: {type: 'string'}},
              required: ['country'],
            },
          },
          required: ['address'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('lookup_address', {address: {}});

    expect(response.result).toMatch(/\/address\/country.*required/i);
  });

  it('throws at register time when the inputSchema is uncompilable and the message names the tool', () => {
